function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 13) return 'nums needs 1 to 13 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -9 || v > 9)) return 'Each score is a whole number from -9 to 9.';
  return null;
}

