function maxStrength(nums) {
  nums.sort((a, b) => a - b);
  let product = 1;
  let taken = 0;

  for (let i = 0; i + 1 < nums.length && nums[i + 1] < 0; i += 2) {
    product *= nums[i] * nums[i + 1];
    taken += 2;
  }
  for (const num of nums) {
    if (num > 0) {
      product *= num;
      taken++;
    }
  }
  if (taken === 0) {
    return nums[nums.length - 1];
  }
  return product;
}

