function maxStrength(nums) {
  // Try every non-empty subset and keep the biggest product.
  const n = nums.length;
  let best = -Infinity;
  for (let mask = 1; mask < (1 << n); mask++) {
    let product = 1;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) product *= nums[i];
    }
    if (product > best) best = product;
  }
  return best;
}

