function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(1, 8) : pick(11, 13);
  const mode = Math.floor(rand() * 5);
  const value = () => {
    if (mode === 0) return pick(-9, 9);
    if (mode === 1) return pick(-9, 0);
    if (mode === 2) return rand() < 0.5 ? 0 : pick(-9, 9);
    if (mode === 3) return pick(-9, -1);
    return rand() < 0.3 ? pick(-1, 1) : pick(-9, 9);
  };
  return [Array.from({ length: n }, value)];
}
